-- Modify "tools" table
ALTER TABLE "tools" ADD COLUMN "org_id" bigint NOT NULL DEFAULT 0, ADD COLUMN "server_id" bigint NULL, ADD COLUMN "description" character varying NOT NULL DEFAULT '', ADD COLUMN "input_schema" jsonb NULL, ADD COLUMN "schema_hash" character varying NOT NULL DEFAULT '', ADD COLUMN "risk_level" character varying NOT NULL DEFAULT 'high_risk', ADD COLUMN "suggested_risk" character varying NOT NULL DEFAULT 'high_risk', ADD COLUMN "annotations" jsonb NULL, ADD COLUMN "approver_ids" jsonb NULL, ADD COLUMN "approval_timeout_sec" bigint NOT NULL DEFAULT 1800, ADD COLUMN "needs_review" boolean NOT NULL DEFAULT false, ADD COLUMN "removed" boolean NOT NULL DEFAULT false;
-- Create index "tool_org_id" to table: "tools"
CREATE INDEX "tool_org_id" ON "tools" ("org_id");
-- Create index "tool_server_id" to table: "tools"
CREATE INDEX "tool_server_id" ON "tools" ("server_id");
-- Create "mcp_servers" table
CREATE TABLE "mcp_servers" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "org_id" bigint NOT NULL, "name" character varying NOT NULL, "description" character varying NOT NULL DEFAULT '', "url" character varying NOT NULL, "transport" character varying NOT NULL DEFAULT 'streamable_http', "headers_enc" bytea NULL, "header_names" jsonb NULL, "timeout_sec" bigint NOT NULL DEFAULT 30, "enabled" boolean NOT NULL DEFAULT true, "last_status" character varying NOT NULL DEFAULT '', "last_error" character varying NOT NULL DEFAULT '', "discovered_at" timestamptz NULL, "created_by" bigint NOT NULL, PRIMARY KEY ("id"));
-- Create index "mcpserver_org_id_name" to table: "mcp_servers"
CREATE UNIQUE INDEX "mcpserver_org_id_name" ON "mcp_servers" ("org_id", "name");
